"""
SMS check-in bot for Reentry Trust Network OS (Flask + Twilio + Postgres/Supabase).

What people can text (any capitals, extra words are fine):
  HERE, OK, DONE, CHECKIN          check in for today (counts once per day)
  HELP                             how to ask for local resources
  <zip> <need>, like "60617 food"  up to 3 verified local resources
Anything else gets the menu back. A text the bot doesn't understand is never
logged as a missed check-in and never touches anyone's streak.

Only the phone number, zip code and check-in times are stored. Message text
is never saved.
"""
import os
import re
from datetime import datetime, timedelta, timezone
from xml.sax.saxutils import escape
from zoneinfo import ZoneInfo

import psycopg2
from flask import Flask, Response, abort, request
from psycopg2.extras import RealDictCursor
from twilio.request_validator import RequestValidator
from werkzeug.middleware.proxy_fix import ProxyFix

DB_URL = os.environ["SUPABASE_DB_URL"]
TWILIO_AUTH_TOKEN = os.environ["TWILIO_AUTH_TOKEN"]
LOCAL_TZ = ZoneInfo(os.environ.get("BOT_TIMEZONE", "America/New_York"))

app = Flask(__name__)
# Railway and Render put HTTPS in front of the app. Without this the app thinks
# its own URL is http://, and every Twilio signature check fails.
app.wsgi_app = ProxyFix(app.wsgi_app, x_proto=1, x_host=1)
validator = RequestValidator(TWILIO_AUTH_TOKEN)

CHECKIN_WORDS = {"here", "ok", "okay", "done", "checkin", "present"}
CHECKIN_PHRASES = {"in", "check in", "checking in", "im in", "i'm in"}
NEGATIONS = {"not", "no", "cant", "can't", "wont", "won't", "never"}
HELP_WORDS = {"help", "resource", "resources", "need", "menu"}
NEEDS = {
    "housing": "housing", "house": "housing", "shelter": "housing", "bed": "housing",
    "job": "job", "jobs": "job", "work": "job",
    "id": "id_docs", "ids": "id_docs", "license": "id_docs",
    "food": "food",
    "legal": "legal", "lawyer": "legal",
    "counseling": "mental_health", "therapy": "mental_health",
}
NEED_LABELS = {"housing": "housing", "job": "job", "id_docs": "ID", "food": "food",
               "legal": "legal", "mental_health": "mental health"}

WELCOME = "Welcome. We only keep your phone number and the days you check in. Text STOP anytime to quit. "
MENU = ("Text HERE to check in for today. Text your zip code and what you need, "
        "like 60617 housing, to get local resources (housing, job, ID, food, legal).")
HELP_REPLY = ("We got you. Text your zip code and what you need, like 60617 housing. "
              "Options: housing, job, ID, food, legal. In a crisis, call or text 988.")


def parse_message(body: str) -> dict:
    """Decide what a text means. Pure function, no database."""
    text = " ".join(body.lower().split())
    words = re.findall(r"[a-z0-9']+", text)
    zip_code = next((w for w in words if re.fullmatch(r"\d{5}", w)), None)
    need = next((NEEDS[w] for w in words if w in NEEDS), None)
    if zip_code or need:
        return {"intent": "resources", "zip": zip_code, "need": need}
    if (NEGATIONS | HELP_WORDS) & set(words):
        return {"intent": "help"}
    if len(words) <= 5 and (CHECKIN_WORDS & set(words) or text.strip(".!") in CHECKIN_PHRASES):
        return {"intent": "checkin"}
    return {"intent": "menu"}


def get_or_create_user(cur, phone):
    cur.execute(
        "INSERT INTO app_user (phone) VALUES (%s) ON CONFLICT (phone) DO NOTHING RETURNING id", (phone,)
    )
    is_new = cur.fetchone() is not None
    # Row lock: two texts arriving at once can't both count as today's check-in.
    cur.execute("SELECT * FROM app_user WHERE phone=%s FOR UPDATE", (phone,))
    return cur.fetchone(), is_new


def check_in(cur, user):
    """Count at most one check-in per local day. Returns (streak, counted_now)."""
    now = datetime.now(timezone.utc)
    today = now.astimezone(LOCAL_TZ).date()
    cur.execute(
        "SELECT created_at FROM check_in WHERE user_id=%s AND status='on_time' "
        "ORDER BY created_at DESC LIMIT 1",
        (user["id"],),
    )
    last = cur.fetchone()
    last_day = last["created_at"].replace(tzinfo=timezone.utc).astimezone(LOCAL_TZ).date() if last else None
    if last_day == today:
        return user["streak_count"], False
    streak = user["streak_count"] + 1 if last_day == today - timedelta(days=1) else 1
    cur.execute(
        "INSERT INTO check_in (user_id, status, created_at) VALUES (%s, 'on_time', %s)",
        (user["id"], now.replace(tzinfo=None)),  # stored as UTC
    )
    cur.execute("UPDATE app_user SET streak_count=%s WHERE id=%s", (streak, user["id"]))
    return streak, True


def find_resources(cur, zip_code, need):
    cur.execute(
        "SELECT name, contact FROM resource WHERE zip_code=%s AND category=%s AND verified "
        "ORDER BY name LIMIT 3",
        (zip_code, need),
    )
    return cur.fetchall()


def days(n):
    return f"{n} day" if n == 1 else f"{n} days"


def reply_for(cur, user, msg) -> str:
    if msg["intent"] == "checkin":
        streak, counted = check_in(cur, user)
        if counted:
            return f"Checked in for today. Streak: {days(streak)}. Keep going, you got this."
        return f"You already checked in today. Streak: {days(streak)}. See you tomorrow."

    if msg["intent"] == "resources":
        zip_code = msg["zip"] or user.get("zip_code")
        if msg["zip"]:
            cur.execute("UPDATE app_user SET zip_code=%s WHERE id=%s", (msg["zip"], user["id"]))
        if not msg["need"]:
            return f"What do you need near {zip_code}? Text it like: {zip_code} housing (or job, ID, food, legal)."
        label = NEED_LABELS[msg["need"]]
        if not zip_code:
            return f"What's your zip code? Text it with what you need, like: 60617 {label}."
        found = find_resources(cur, zip_code, msg["need"])
        if not found:
            return f"No verified {label} listings near {zip_code} yet. We add more every week. Text HELP anytime."
        lines = [f"{i}. {r['name']} - {r['contact']}" for i, r in enumerate(found, 1)]
        return f"{label.capitalize()} near {zip_code}:\n" + "\n".join(lines)

    if msg["intent"] == "help":
        return HELP_REPLY
    return MENU


@app.route("/sms", methods=["POST"])
def sms_webhook():
    if not validator.validate(request.url, request.form, request.headers.get("X-Twilio-Signature", "")):
        abort(403)  # not from Twilio: never let anyone post fake check-ins
    phone = request.form.get("From", "")
    msg = parse_message(request.form.get("Body", ""))
    conn = psycopg2.connect(DB_URL, cursor_factory=RealDictCursor)
    try:
        with conn, conn.cursor() as cur:
            user, is_new = get_or_create_user(cur, phone)
            reply = reply_for(cur, user, msg)
    finally:
        conn.close()
    if is_new:
        reply = WELCOME + reply
    return Response(f"<Response><Message>{escape(reply)}</Message></Response>", mimetype="text/xml")


@app.route("/health", methods=["GET"])
def health():
    return {"status": "ok", "time": datetime.now(timezone.utc).isoformat()}


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)))
